"""Private A110 scientific goal."""
from __future__ import annotations
from .scientific_assignment_contracts import INSTRUCTION_VERSION, selection_fields
from gene_annotation_episode.episodic_workflow.root.a110.communication import plain
from gene_annotation_episode.episodic_workflow.root.a110.domain import ContractError

def scientific_guidance():
    from gene_annotation_episode.episodic_workflow.root.a110.component_axis_workflow import INSTRUCTIONS, finding_progress, task_context
    return INSTRUCTIONS['A110'] + '\n\nScientific descendants remain A110. Use available shared operations for specific parent information needs or useful received findings. The immediate parent chooses within its own options or relays the need upward; publication does not commission work or promise a reply. Preserve named scientific components separately from controller progress.\n\n'

class ScientificGoal:

    def instructions(self, context):
        self.validate_context(context)
        selection = context.assignment['selection']
        axis = self.library.resolve(selection[selection_fields(selection)[0]])
        axis_guidance = ''
        from gene_annotation_episode.episodic_workflow.root.a110.scientific_process.goal import scientific_guidance
        axis_guidance = scientific_guidance()
        if axis.get('entry_version') == INSTRUCTION_VERSION:
            return axis_guidance + "Determine what the supplied target does within the parent's assigned question, scope and constraints. Start with the supplied sequence, selected file contents or snippets, preserving their boundaries, completeness and known context. No initial candidate annotation or publicly searchable name is required. Possible functions can emerge from the evidence and be compared or revised. Apply the complete selected investigation instructions and thought-pattern guidance on every decision. Use actual outcomes and received child results to choose and revise your approach. Selected instructions describe how to investigate; they are not evidence about this target. Preserve the measured subject, conditions, controls, native measurements, uncertainty and limits of inference when interpreting evidence. Missing information remains unknown.\n\nChoose an available tool action, commit a scientific interpretation through the reasoning action, commission a scoped child with its own typed return form, or wait for selected pending work when that informs the investigation. Use only the selected actual tools and their supplied resource instructions; choose callable operands through the declared response contract. Preserve the parent's exact requested result meanings and allowed values. Recorded facts come from actual records. Keep inherited information distinct from new findings and completed work distinct from attempts. Return valid partial findings and specific failures through the requested form.\n\nKeep the assigned evidence axis, thought pattern and selected tools for this episode. process.revise prepares a different thought pattern and/or tool selection for a new child; it does not change this episode or start that child. To commission that alternative, copy its selection and revision_origin into a separately selected child assignment with the child's job, scope, constraints and typed return. Children own their iterative choices. The configured controller owns continuation. Waiting and unchanged observations do not manufacture progress."
        return "Investigate the parent's assigned scientific problem iteratively in the shared Episode loop. The selected scientific support proposition and operands define the support problem; the thought pattern supplies alternatives and outcome-sensitive guidance; the selected real tools supply their exact callable contracts. Choose your own actions using actual outcomes and received child forms. The selection is no prescribed sequence or automatic compatibility verdict. Library sources are instruction provenance, not scientific evidence about this target. Inspect actual source subjects, conditions and target applicability before interpreting evidence. annotation_support_routes describes the actual separately bound annotation policy's kind dispatch. An unmapped kind has no base-axis mapping in that known policy. Unavailable metadata means this reader cannot declare the bound policy; it is no verdict on evidence or the actual score. Metadata itself earns no credit and never replaces or filters the actual projectors, annotation formula or continuation rule. Keep the parent's objective, scope, constraints and exact typed form; support metadata never adds form fields or scoring axes. Use common reasoning to commit scientific interpretations. Keep the originally assigned scientific support, thought pattern and selected tool set throughout this episode. Explicit process.revise prepares a selection for a new child; a separately selected episode_child action commissions that child with its own job, scope, constraints and typed return form. Preparation changes no current process and starts no child. Copy both result.selection and revision_origin into that child's assignment to identify it as an alternative approach. Request the recorded scientific_process_results source in child forms when their process relationships and existing closed credit/yield are needed for steering. Only retrieved actual tools are available; their descriptions do not grant execution. The configured controller owns continuation."
